import sas.*;
import java.awt.Color;
public class Hai
{
    private Picture hai;

    public Hai()
    {   hai = new Picture(800, 150,400,200,"hai.png");
        hai.flipHorizontal();
    }

    public void reset() {
      hai.moveTo(800, 150);
    }


    public void bewege(int pDistanz){
       hai.move(-pDistanz, 0);
       if (hai.getShapeX() + hai.getShapeWidth() < 0) {
         zurueck();
     }
    }

    private void zurueck(){
     double yPos = Tools.randomNumber(50,200);
     hai.moveTo(800, yPos);
    }

    public boolean frisst(Fisch2 fisch) {
        return hai.intersects(fisch.gibGrafik());
    }
}

